import{pixelSignature}from'./reconstruction-ground.js';
const copy=v=>structuredClone(v),hash=v=>pixelSignature(new TextEncoder().encode(JSON.stringify(v)));
export function addRecognisedStamp(project,map,template,captured){const rules=copy(captured.rules).map(r=>({...r,exactArtwork:true,reuseNativeComposite:true})),id='recognised-'+template.id+'-'+hash([rules,captured.renderIntents,map.rom.engine]),old=project.romObjects?.find(t=>t.id===id);if(old)return old;if((project.romObjects?.length||0)>=512)throw Error('The object stamp collection is full.');const stamp={...copy(template),id,sourceTemplateId:template.id,name:template.name,category:'Recognised objects · '+(map.rom.label||map.name),rules,renderIntents:copy(captured.renderIntents),sourceId:map.rom.sourceId,sourceEngine:map.rom.engine,sourceKey:map.rom.key,atlasId:map.rom.atlasId,layerCount:map.rom.metatileLayers||2,entrances:[],stampOnly:true,nativeStamp:true};delete stamp.pixels;delete stamp.colours;(project.romObjects??=[]).push(stamp);return stamp;}
export async function makeBackgroundStamps({map,assembly,cells,planes,encode}){const assets=[],templates=[],seen=new Set();for(let i=0;i<cells.length;i++){const p=planes[i],rule={...copy(cells[i].rule),exactArtwork:true,reuseNativeComposite:true},id='repair-tile-'+hash([p.map(pixelSignature),rule,map.rom.engine]);if(seen.has(id))continue;seen.add(id);const planeIds=[];for(let l=0;l<p.length;l++){const aid=id+'-'+l;assets.push({id:aid,name:'Repaired background · plane '+l,width:16,height:16,tileSize:16,category:'Repaired wall and floor tiles',data:await encode({width:16,height:16,pixels:p[l]})});planeIds.push(aid);}const wall=!!rule.collision&&assembly.reconstruction?.surfaceHint==='wall',layers=Object.fromEntries(['ground','details','objects','overhead'].map(k=>[k,[null]]));for(let l=0;l<p.length;l++)layers[['ground','details','overhead'][l]][0]={a:planeIds[l],sx:0,sy:0,size:16,renderRole:l===0?'ground':p.length===3&&l===2?'foreground':'behind'};const composite=new Uint8ClampedArray(1024);for(const plane of p)for(let j=0;j<1024;j+=4)if(plane[j+3])composite.set(plane.subarray(j,j+4),j);templates.push({id,preview:await encode({width:16,height:16,pixels:composite}),name:(wall?'Wall':'Floor')+' · '+assembly.name+' '+(i+1),category:'Repaired tiles · '+(wall?'Walls':'Floors'),w:1,h:1,layers,rules:[rule],renderIntents:[{version:1,layerType:rule.layerType??1}],sourceId:map.rom.sourceId,sourceEngine:map.rom.engine,atlasId:map.rom.atlasId,layerCount:p.length,entrances:[],stampOnly:true,portableBackground:true});}return{assets,templates};}
export function installBackgroundStamps(project,pack){const add=pack.assets.filter(a=>!project.assets.some(v=>v.id===a.id)),templates=pack.templates.filter(t=>!project.romObjects?.some(v=>v.id===t.id));if(project.assets.length+add.length>512||(project.romObjects?.length||0)+templates.length>512)throw Error('The repaired tile collection exceeds this project’s limits.');project.assets.push(...copy(add));(project.romObjects??=[]).push(...copy(templates));return templates;}
